        end },
        { name = "paste_to_spear", run = function(t)
            -- LEG 3 BEGIN: makeKarambwanjiPaste
            t.ticks(3)
            -- the pack is nearly full (leg 2 leftovers): drop the bycatch shrimp (guide: not needed)
            for i = 1, 6 do t.player.drop("raw_shrimp") t.ticks(1) end
            local _, shrimp = t.inv.count("raw_shrimp")
            t.check("leg3.pack-drop", shrimp == 0, "dropped the bycatch raw shrimp, left: " .. tostring(shrimp))
            -- guide items for leg 3, brought along: pestle and mortar, an iron or better spear, an agility potion (4)
            t.cheat("::give pestle_and_mortar 1")
            t.cheat("::give iron_spear 1") -- guide: Iron spear or better (givePotion/giveSpear)
            t.cheat("::give 4dose1agility 1") -- guide: Agility Potion (4)
            t.cheat("::complete quest_druidicritual") -- prerequisite of Jungle Potion: the pestle and mortar needs Herblore unlocked (makeKarambwanjiPaste)
            t.cheat("::setlevel fishing 65") -- guide: Karambwan fishing needs Fishing 65 (getPoisonKarambwan), or buy from the GE
            t.ticks(3)
            t.exec("leg3.gives", t.inv.await_all, { pestle_and_mortar = 1, iron_spear = 1, ["4dose1agility"] = 1 }, 10)

            -- raw karambwanji: three are needed (paste, vessel load, spare)
            -- the Holy Lake is west of the river: the log, then open ground to the bank tile north of
            -- the spot (2791,3021 is a jungle tree; 2791,3020 is open, as in leg 1). One visit nets the
            -- whole supply: a vessel load takes ONE karambwanji (quest_tbwt.rs2:102-111 inv_del 1), and
            -- a karambwan try spends that load either way (tbwt.rs2 attempt_fish_karambwan :118-131).
            if not cross_log(t, "fishKarambwaji3.logWest", false) then return end
            t.exec("goto-fishKarambwaji3", t.player.goto_tile, 2791, 3020, 0)
            local sr, sa, sb = t.npc.tiles("0_43_47_karambwanji", 15)
            t.check("fishKarambwaji3.spot", sr == "ok", "spot copies: " .. tostring(sr) .. " " .. tostring(sa) .. " " .. tostring(sb))
            net_karambwanji(t, "fishKarambwaji3", 12)
            t.exec("goto-leave-spot3", t.player.goto_tile, 2791, 3030, 0)

            t.exec("makeKarambwanjiPaste", t.player.use_item_on_item, "pestle_and_mortar", "tbwt_raw_karambwanji")
            t.exec("makeKarambwanjiPaste.has", t.inv.await, "tbwt_raw_karambwanji_paste", 1, 20)
            t.exec("usePasteOnBones", t.player.use_item_on_item, "tbwt_burnt_jogre_bones", "tbwt_raw_karambwanji_paste")
            t.exec("usePasteOnBones.has", t.inv.await, "tbwt_burnt_jogre_bones_in_raw_karambwanji_paste", 1, 20)

            -- getPoisonKarambwan: back over the log to Tiadeche's spot; each try loads one karambwanji
            if not cross_log(t, "getPoisonKarambwan.logEast", true) then return end
            t.exec("goto-getPoisonKarambwan", t.player.goto_tile, 2912, 3115, 0)
            for i = 1, 10 do
                local _, bait = t.inv.count("tbwt_raw_karambwanji")
                if bait < 1 then break end
                t.exec("getPoisonKarambwan-load" .. i, t.player.use_item_on_item, "tbwt_raw_karambwanji", "tbwt_karambwan_vessel")
                t.exec("getPoisonKarambwan-load" .. i .. ".loaded", t.inv.await, "tbwt_karambwan_vessel_loaded_with_karambwanji", 1, 5)
                t.exec("getPoisonKarambwan-fish" .. i, t.player.press, "general_karambwan", 1, 20)
                t.ticks(10)
                local _, rk = t.inv.count("tbwt_raw_karambwan")
                t.check("getPoisonKarambwan-try" .. i, true, "raw karambwan after try " .. i .. ": " .. tostring(rk) .. " (the vessel is spent either way; the gift from Tiadeche is one of them)")
                if rk >= 3 then break end
            end
            local _, rk2 = t.inv.count("tbwt_raw_karambwan")
            t.check("getPoisonKarambwan", rk2 >= 1, "raw karambwan in the pack: " .. tostring(rk2))

            -- cookBones / cookKarambwan on the fire south of Tai Bwo Wannai (2790,3048)
            if not cross_log(t, "cookBones.logWest", false) then return end
            t.exec("goto-cookBones", t.player.goto_tile, 2790, 3051, 0)
            t.exec("cookBones", t.player.use_on, "tbwt_burnt_jogre_bones_in_raw_karambwanji_paste", t.player.by_symbol("loc", "fire"))
            t.exec("cookBones.has", t.inv.await, "tbwt_burnt_jogre_bones_marinated_in_karambwanji", 1, 20)
            for i = 1, 5 do
                local _, raw = t.inv.count("tbwt_raw_karambwan")
                if raw < 1 then break end
                t.exec("cookKarambwan" .. i, t.player.use_on, "tbwt_raw_karambwan", t.player.by_symbol("loc", "fire"))
                t.ticks(4)
                local _, pc = t.inv.count("tbwt_poorly_cooked_karambwan")
                if pc >= 1 then break end
            end
            t.exec("cookKarambwan", t.inv.await, "tbwt_poorly_cooked_karambwan", 1, 10)
            t.exec("usePestleOnKarambwan", t.player.use_item_on_item, "pestle_and_mortar", "tbwt_poorly_cooked_karambwan")
            t.exec("usePestleOnKarambwan.has", t.inv.await, "tbwt_poisonous_karambwan_paste", 1, 20)
            t.exec("usePasteOnSpear", t.player.use_item_on_item, "tbwt_poisonous_karambwan_paste", "iron_spear")
            t.exec("usePasteOnSpear.has", t.inv.await, "tbwt_iron_spear_kp", 1, 20)

            -- Tamayu (2845,3041): first talk is the good-news chain, then "When will you succeed?" + Yes plays the hunt cutscene
            t.exec("goto-talkToTamayu1", t.player.goto_tile, 2846, 3041, 0)
            t.exec("talkToTamayu1-news", t.player.talk_to, "tbwt_tamayu", 1)
            t.exec("talkToTamayu1-news-dialog", t.chat.play, {
                "player:Tamayu, first son of Timfraku",
                "npc:I am.",
                "player:Tamayu, I bring good news",
                "player:Your father requests",
                "npc:Then know this",
                "npc:I vow upon the blood",
                "player:You could slay it",
                "npc:No!",
            })
            t.ticks(2)
            t.exec("talkToTamayu1", t.player.talk_to, "tbwt_tamayu", 1)
            t.exec("talkToTamayu1-dialog", t.chat.play, {
                "options",
                "choose:When will you succeed?",
                "player:When will you succeed",
                "npc:When the gods bless me",
                "options",
                "choose:Yes",
                "player:Lead the way",
            })
            t.exec("talkToTamayu1.cutscene", t.cutscene.await, "talkToTamayu1", { expect = { { op = "reset" } } })
            t.exec("talkToTamayu1-assess", t.chat.play, {
                "npc:I simply cannot match",
                "npc:I cannot do enough damage",
                "npc:",
            })
            t.ticks(2)

            t.exec("givePotion", t.player.use_on, "4dose1agility", t.player.by_symbol("npc", "tbwt_tamayu"))
            t.exec("givePotion-dialog", t.chat.play, {
                "player:I've noticed you commenting",
                "mesbox:You hand over the agility potion",
                "npc:Thank you Bwana",
            })
            t.ticks(6)
            t.exec("givePotion-agile", t.chat.play, { "npc:I feel agile enough" })
            t.ticks(2)
            t.exec("giveSpear", t.player.use_on, "tbwt_iron_spear_kp", t.player.by_symbol("npc", "tbwt_tamayu"))
            t.exec("giveSpear-dialog", t.chat.play, {
                "player:Tamayu, try using this weapon",
                "mesbox:You hand the spear",
                "npc:Thank you Bwana",
            })
            t.ticks(2)
            -- LEG 3 END
            local _, l3stage = t.quest.stage()
            local _, l3tile = t.world.tile()
            local _, tam = t.var.server("varp6053_tbwt_tamayu")
            t.check("leg.3.end", tam == 3, "tile " .. tostring(l3tile.x) .. "," .. tostring(l3tile.z) .. " level " .. tostring(l3tile.level) .. ", varp320_tbwt_main=" .. tostring(l3stage) .. ", varp6053_tbwt_tamayu=" .. tostring(tam) .. ", Tamayu holds the poisoned spear and the agility potion; pack: banana rum, marinated burnt bones, seaweed, knife, tinderbox, sharks")
        end },
        { name = "hunt_to_end", run = function(t)
            -- LEG 4 BEGIN: goOnHuntToKill
            t.ticks(3)
            t.exec("goOnHuntToKill", t.player.talk_to, "tbwt_tamayu", 1)
            t.exec("goOnHuntToKill-dialog", t.chat.play, {
                "options",
                "choose:/Take me on your next hunt/",
                "player:Take me on your next hunt",
                "npc:Very well, but you must not interfere",
            })
            t.exec("goOnHuntToKill.cutscene", t.cutscene.await, "goOnHuntToKill", { expect = { { op = "reset" } } })
            t.ticks(4)
            local _, tam = t.var.server("varp6053_tbwt_tamayu")
            t.check("goOnHuntToKill.var", tam == 4, "varp6053_tbwt_tamayu = " .. tostring(tam) .. " after the killing hunt")

            -- getMonkeyCorpse: the corpse drops only for a monkey killed at range or by magic (tbwt_monkey.rs2:20-31, :53-60)
            t.exec("goto-getMonkeyCorpse", t.player.goto_tile, 2834, 3032, 0)
            -- wind strike does 1-2 damage to a 3-hit-point monkey (30 in the client's tenths): re-cast until its corpse lies on the ground
            local casts, corpse_down = 0, false
            while casts < 30 and not corpse_down do
                casts = casts + 1
                local cr0, cd0 = t.player.cast("wind_strike", "monkey", 8)
                if casts == 1 then t.check("getMonkeyCorpse", cr0 == "ok", "first wind strike: " .. tostring(cd0)) end
                t.ticks(3)
                corpse_down = (t.world.obj_near("tbwt_monkey_corpse", 8) == "ok")
            end
            t.check("getMonkeyCorpse-dead", corpse_down, "monkey killed with wind strike after " .. tostring(casts) .. " cast(s); tbwt_monkey_corpse on the ground: " .. tostring(corpse_down))
            -- pickupCorpse: Take on the dropped tbwt_monkey_corpse
            t.exec("pickupCorpse", t.player.click_obj, "tbwt_monkey_corpse", 3)
            local cr, cn = t.inv.await("tbwt_monkey_corpse", 1, 20)
            t.check("pickupCorpse.has", cr == "ok", "monkey corpse in the backpack: " .. tostring(cn))

            -- useCorpseOnTamayu: tbwt_tamayu.rs2:48-74 -- he skins it now that he has slain the Shaikahan
            t.exec("goto-useCorpseOnTamayu", t.player.goto_tile, 2846, 3040, 0)
            t.exec("useCorpseOnTamayu", t.player.use_on, "tbwt_monkey_corpse", t.player.by_symbol("npc", "tbwt_tamayu"))
            t.exec("useCorpseOnTamayu-dialog", t.chat.play, {
                "npc:Let me guess",
                "mesbox:You hand over the monkey corpse to Tamayu",
            })
            t.ticks(6)
            t.exec("useCorpseOnTamayu-skin", t.chat.play, { "mesbox:Tamayu hands you some monkey skin and bones" })
            t.ticks(2)
            local _, skin = t.inv.count("tbwt_monkey_skin")
            t.check("useCorpseOnTamayu.has", skin == 1, "monkey skin in the backpack: " .. tostring(skin))

            -- makeSeaweedSandwich: tbwt_monkey_skin is the clicked item (quest_tbwt.rs2 [opheldu,tbwt_monkey_skin])
            t.exec("makeSeaweedSandwich", t.player.use_item_on_item, "seaweed", "tbwt_monkey_skin")
            t.ticks(2)
            local _, sw = t.inv.count("tbwt_seaweed_in_monkey_skin_sandwich")
            t.check("makeSeaweedSandwich.has", sw == 1, "seaweed in monkey skin sandwiches: " .. tostring(sw))

            -- talkToTinsay: Cairn Isle (2764,2975), plain travel (the guide names fairy ring CKR only as the way there)
            -- Cairn Isle: open ground to the climbing rocks' east foot (reach.py 2846,3039 -> 2796,2979:
            -- REACH closed-doors 110), the rocks (Agility 15 westbound), then the log bridge on foot
            t.exec("goto-talkToTinsay", t.player.goto_tile, 2796, 2979, 0)
            cairn_rocks(t, "talkToTinsay.rocksWest", true)
            if not cairn_bridge(t, "talkToTinsay.bridgeWest", true) then return end
            t.exec("talkToTinsay", t.player.talk_to, "tbwt_tinsay", 1)
            t.exec("talkToTinsay-dialog", t.chat.play, {
                "npc:Braaar! Tinsay's the name",
                "player:Tinsay, I bring good news",
                "player:Your father requests",
                "npc:I will return only once",
                "player:Where is the tribal statue",
                "npc:Just near my father's hut",
                "player:But that's in the village",
                "npc:I know.",
                "player:So what are you doing here",
                "npc:I'm",
                "player:And I suppose you want me",
                "npc:Good idea",
                "player:You mean you were just sitting",
                "npc:Yes...",
                "player:And you don't see anything wrong",
                "npc:No...",
                "player:Right",
            })
            t.ticks(8)
            t.exec("talkToTinsay-dialog2", t.chat.play, {
                "npc:Hmm ... I think I need banana",
                "player:I see. And you're going to use this",
                "npc:But of course",
                "player:... I'll be back later",
            })
            t.ticks(2)
            local _, tin = t.var.server("varp6054_tbwt_tinsay")
            t.check("talkToTinsay.var", tin == 2, "varp6054_tbwt_tinsay = " .. tostring(tin) .. " after the first talk (fetch banana rum)")

            -- talkToTinsay (2nd visit): banana in Karamjan rum, tbwt_tinsay.rs2:272-285
            t.exec("talkToTinsay-banana", t.player.talk_to, "tbwt_tinsay", 1)
            t.exec("talkToTinsay-banana-dialog", t.chat.play, {
                "npc:Have you found my banana in Karamjan rum",
                "options",
                "choose:Yes.",
                "player:Yes, I have it right here",
                "mesbox:You hand Tinsay the sliced bananas",
            })
            t.ticks(8)
            t.exec("talkToTinsay-banana-dialog2", t.chat.play, {
                "npc:Yes ... that's it",
                "player:What? I thought you needed",
                "npc:I did!",
                "player:Can we return to the village now",
                "npc:Not yet",
                "player:What is it?",
                "npc:I'm thinking",
            })
            t.ticks(8)
            t.exec("talkToTinsay-banana-dialog3", t.chat.play, {
                "npc:Seaweed ... Yes",
                "npc:Aha!",
                "player:Is this really necessary",
                "npc:Yes. Essential",
                "player:I'll be back later",
            })
            t.ticks(2)
            _, tin = t.var.server("varp6054_tbwt_tinsay")
            t.check("talkToTinsay-banana.var", tin == 4, "varp6054_tbwt_tinsay = " .. tostring(tin) .. " (fetch_seaweedsandwich)")

            -- talkToTinsay (3rd visit): the seaweed in monkey skin sandwich
            t.exec("talkToTinsay-sandwich", t.player.talk_to, "tbwt_tinsay", 1)
            t.exec("talkToTinsay-sandwich-dialog", t.chat.play, {
                "npc:Have you found my seaweed in monkey skin sandwich",
                "options",
                "choose:Yes.",
                "player:Yes, I have it right here",
                "mesbox:You hand Tinsay the seaweed in monkey skin sandwich",
            })
            t.ticks(8)
            t.exec("talkToTinsay-sandwich-dialog2", t.chat.play, {
                "npc:Yes ... perfect",
                "player:Can we go now",
                "npc:Erm",
                "player:...",
                "npc:...",
                "player:...",
                "npc:...",
                "player:Say something",
                "npc:No!",
                "player:Does that mean",
                "npc:I'm not coming",
                "player:Why?",
                "npc:I need one more thing",
                "player:Jogre bones?",
                "npc:Yes ... burnt Jogre bones",
                "player:... burnt Jogre bones??",
                "npc:Indeed",
                "player:Marinated???",
                "npc:Marinated in Karambwanji",
                "player:...",
                "npc:Mmm",
                "player:You're just going to eat it",
                "npc:No! Burnt Jogre bones",
                "player:I'll be back",
            })
            t.ticks(2)
            _, tin = t.var.server("varp6054_tbwt_tinsay")
            t.check("talkToTinsay-sandwich.var", tin == 6, "varp6054_tbwt_tinsay = " .. tostring(tin) .. " (fetch_marinatedbones)")

            -- talkToTinsay (4th visit): the burnt jogre bones marinated in karambwanji
            t.exec("talkToTinsay-bones", t.player.talk_to, "tbwt_tinsay", 1)
            t.exec("talkToTinsay-bones-dialog", t.chat.play, {
                "npc:Have you found my burnt Jogre bones marinated",
                "options",
                "choose:Yes.",
                "player:Yes, I have it right here",
                "mesbox:You hand Tinsay the burnt Jogre bones marinated",
            })
            t.ticks(14)
            t.exec("talkToTinsay-bones-dialog2", t.chat.play, {
                "npc:Finally!",
                "player:I assume you're now able",
                "npc:Perfectly able",
                "npc:Probably best you don't",
                "player:Will you return to the village now",
                "npc:Must I",
                "player:I insist",
                "npc:He will not be pleased",
                "player:Why?",
                "npc:It's complicated",
                "npc:Very well. I will meet you",
            })
            t.ticks(2)
            _, tin = t.var.server("varp6054_tbwt_tinsay")
            t.check("talkToTinsay-bones.var", tin == 7, "varp6054_tbwt_tinsay = " .. tostring(tin) .. " (complete)")

            -- useVesselOnTinsay: tbwt_tinsay.rs2:46-72 -- the plain vessel Tiadeche sent along, now that Tinsay is satisfied
            t.exec("useVesselOnTinsay", t.player.use_on, "tbwt_karambwan_vessel", t.player.by_symbol("npc", "tbwt_tinsay"))
            t.exec("useVesselOnTinsay-dialog", t.chat.play, {
                "player:Your brother Tiadeche has sent me",
                "npc:Very well - hand it over",
                "mesbox:You hand over the Karambwan vessel to Tinsay",
            })
            t.ticks(6)
            t.exec("useVesselOnTinsay-dialog2", t.chat.play, {
                "mesbox:Tinsay hands you a Karambwan vessel crafting manual",
                "npc:I hope that's what he wanted",
            })
            t.ticks(2)
            local _, manual = t.inv.count("tbwt_crafting_manual")
            t.check("useVesselOnTinsay.has", manual == 1, "crafting manuals in the backpack: " .. tostring(manual))

            -- off Cairn Isle: the bridge east (a fall lands on the mainland's south bank: no rocks then)
            if cairn_bridge(t, "leaveCairn.bridgeEast", false) == "crossed" then
                cairn_rocks(t, "leaveCairn.rocksEast", false)
            end
            if not cross_log(t, "goToTiadecheFinal.logEast", true) then return end

            -- goToTiadecheFinal: Tiadeche north of fairy ring DKP (2912,3116); use the manual on him (tbwt_tiadeche.rs2:89-93, :183-187)
            t.exec("goto-goToTiadecheFinal", t.player.goto_tile, 2912, 3114, 0)
            t.exec("goToTiadecheFinal", t.player.use_on, "tbwt_crafting_manual", t.player.by_symbol("npc", "tbwt_tiadeche"))
            t.exec("goToTiadecheFinal-dialog", t.chat.play, {
                "mesbox:You hand over the crafting manual to Tiadeche",
                "npc:Thank you so much",
                "player:Will you return to the village now",
                "npc:Yes. I will do as I promised",
                "player:I am glad to hear this",
                "npc:Not yet",
                "npc:I will meet you in the village",
            })
            t.ticks(2)
            local _, tia = t.var.varp("varp321_tbwt_tiadeche")
            local _, mainstage = t.quest.stage()
            t.check("goToTiadecheFinal.var", mainstage == 4, "varp321_tbwt_tiadeche = " .. tostring(tia) .. ", varp320_tbwt_main = " .. tostring(mainstage) .. " (completed_all_brothers)")

            -- goToTimfrakuLadderEnd: back up the ladder into Timfraku's hut (as in leg 1)
            if not cross_log(t, "goToTimfrakuLadderEnd.logWest", false) then return end
            t.exec("goto-goToTimfrakuLadderEnd", t.player.goto_tile, 2781, 3089, 0)
            ladder_up(t, "goToTimfrakuLadderEnd")
            -- LEG 4 END of the pre-hand-in rows; the hand-in follows
            -- (XP snapshots are taken before each claim below)
            local _, qp_before = t.var.varp("varp101_qp")

            -- talkToTimfrakuEnd: the option chosen does not matter (tbwt_timfraku.rs2:259-290)
            local coins_before = select(2, t.inv.count("coins"))
            t.exec("talkToTimfrakuEnd", t.player.talk_to, "tbwt_timfraku", 1)
            t.exec("talkToTimfrakuEnd-dialog", t.chat.play, {
                "npc:My sons have returned to the village",
                "npc:please accept my eternal gratitude",
                "options",
                "choose:Oh it was nothing really.",
                "player:Oh it was nothing really",
                "npc:It was? Very well",
                "player:Of course.",
                "mesbox:Timfraku hands you a big stack of gold coins",
            })
            t.ticks(4)
            -- the quest-complete queue also runs tbwt_timfraku_talk_to_sons (quest_tbwt.rs2:317): dismiss it before the scroll check
            t.exec("talkToTimfrakuEnd-sons", t.chat.play, {
                "npc:You should go and see my sons",
                "options",
                "choose:Ok, thanks.",
                "player:Ok, thanks",
            })
            t.ticks(4)
            local _, coins_after = t.inv.count("coins")
            t.check("talkToTimfrakuEnd.coins", coins_after == coins_before + 2000, "coins " .. tostring(coins_before) .. " -> " .. tostring(coins_after) .. " (documented reward: 2000 coins)")
            -- expect_complete's own quest.journal row times out right after scroll.close() (gaps-combat: `quest.journal` can
            -- time out after a real completion), so the four-row shape is written by hand with the rows that land.
            local stage_r, stage_v = t.quest.stage()
            t.check("quest.varp_complete", stage_r == "ok" and stage_v == 6, "varp320_tbwt_main = " .. tostring(stage_v) .. " (complete=6) [" .. tostring(stage_r) .. "]")
            local sr, sd = t.scroll.title()
            local sname = type(sd) == "table" and sd.name or nil
            local shr, shd = t.shot("quest.scroll")
            local shnote = ""
            if shr == "ok" and type(shd) == "string" and string.find(shd, "unchanged", 1, true) then shnote = " [scroll already photographed: " .. shd .. "]" end
            t.step("quest.scroll_title", (sr == "ok" and type(sname) == "string" and string.find(sname, "Tai Bwo Wannai Trio", 1, true) ~= nil) and "PASS" or "FAIL", "scroll title: " .. tostring(sname) .. " (" .. tostring(sr) .. ")" .. shnote)
            local rr, rd = t.scroll.rewards()
            local rtext = type(rd) == "table" and type(rd.lines) == "table" and table.concat(rd.lines, " | ") or tostring(rd)
            t.check("quest.scroll_rewards", rr == "ok" and string.find(rtext, "2 Quest Points", 1, true) ~= nil, "reward scroll lists: " .. rtext)
            -- the scroll lists the four XP rewards (wiki scroll image); the brothers award them below
            for _, pair in ipairs({ { "Fishing", 5000 }, { "Cooking", 5000 }, { "Attack", 2500 }, { "Strength", 2500 } }) do
                local xr, xv = t.scroll.reward_xp(pair[1])
                t.check("quest.scroll_xp." .. pair[1], xr == "ok" and xv == pair[2], pair[1] .. " XP on the scroll: " .. tostring(xr) .. " " .. tostring(xv))
            end
            local cr2 = t.scroll.close()
            t.check("quest.scroll_close", cr2 == "ok", "scroll.close() -> " .. tostring(cr2))
            local qp_r, qp_now = t.var.varp("varp101_qp")
            t.check("quest.points", qp_r == "ok" and qp_now == qp_before + 2, "qp " .. tostring(qp_before) .. " -> " .. tostring(qp_now) .. " (documented reward: 2 Quest Points)")

            -- The XP rewards are claimed from the three brothers in the village after completion
            -- (wiki Tai Bwo Wannai Trio oldid 15265886 Rewards; Quest Helper talkToTimfrakuEnd NOTE;
            -- tbwt_tinsay_final / tbwt_tiadeche_final / tbwt_tamayu_final .rs2 claim_reward).
            -- down the ladder, then each brother's house through its tbwt_bamboo_door (open now the quest
            -- is complete, quest_tbwt.rs2:131-136), in and out
            ladder_down(t, "claimTinsay.ladderDown")
            t.exec("goto-claimTinsay", t.player.goto_tile, 2794, 3054, 0)
            bamboo_door(t, "claimTinsay.doorIn", HOUSE_TINSAY, true)
            local _, s1 = t.skill.snapshot()
            t.exec("claimTinsay", t.player.talk_to, "tbwt_tinsay_multinpc_house", 1)
            t.exec("claimTinsay-dialog", t.chat.play, {
                "npc:Braaar! Your meals are truly excellent",
                "player:I'm glad to hear it.",
                "npc:but there are some areas",
                "player:Such as?",
                "npc:Let me show you.",
                "mesbox:Tinsay trains you in cooking technique.",
                "mesbox:Tinsay teaches you how to cook Karambwan",
                "player:Thanks.",
                "npc:Oh, and before you go",
                "player:Ok...",
            })
            t.ticks(2)
            t.exec("claimTinsay.xp", t.skill.expect_gain, "cooking", 5000, s1)

            bamboo_door(t, "claimTinsay.doorOut", HOUSE_TINSAY, false)
            bamboo_door(t, "claimTiadeche.doorIn", HOUSE_TIADECHE, true)
            local _, s2 = t.skill.snapshot()
            t.exec("claimTiadeche", t.player.talk_to, "tbwt_tiadeche_multinpc_house", 1)
            t.exec("claimTiadeche-dialog", t.chat.play, {
                "npc:Hello, Bwana! We three have finally returned",
                "player:So I see.",
                "npc:I wish to reward you",
                "npc:I have refined my Karambwan fishing technique",
                "mesbox:Tiadeche trains you in fishing technique.",
                "npc:Thanks to you, Lubufu's Karambwan monopoly is over",
                "player:Thanks.",
            })
            t.ticks(2)
            t.exec("claimTiadeche.xp", t.skill.expect_gain, "fishing", 5000, s2)

            bamboo_door(t, "claimTiadeche.doorOut", HOUSE_TIADECHE, false)
            bamboo_door(t, "claimTamayu.doorIn", HOUSE_TAMAYU, true)
            local _, s3 = t.skill.snapshot()
            t.exec("claimTamayu", t.player.talk_to, "tbwt_tamayu_multinpc_house", 1)
            t.exec("claimTamayu-dialog", t.chat.play, {
                "npc:Welcome back to Tai Bwo Wannai, stranger.",
                "player:I no longer feel a stranger here.",
                "npc:And neither do we",
                "npc:I have not much of worth to give",
                "mesbox:Tamayu trains you in fighting technique.",
                "player:Thanks.",
                "npc:This is the one thing I can give",
                "mesbox:Tamayu hands you some kind of spear.",
                "npc:Take care, Bwana.",
            })
            t.ticks(2)
            t.exec("claimTamayu.xp-attack", t.skill.expect_gain, "attack", 2500, s3)
            t.exec("claimTamayu.xp-strength", t.skill.expect_gain, "strength", 2500, s3)
            t.exec("claimTamayu.spear", t.inv.await, "tbwt_rune_spear_kp", 1, 5)
            t.finish(0)
        end },
    },
}
